from PIL import Image
im = Image.open('r149-sgroup-light.png').convert('RGB')
def px(x,y): return im.getpixel((x,y))
def boxx(y):
    xs=[x for x in range(0,60) if px(x,y)!=(228,228,228) and sum(px(x,y))<680]
    return (min(xs),max(xs)) if xs else None
